/* From Uiverse.io by mrtqzbek11 - Tags: button */
.__UIV_SCOPE__ button {
  width: 136px;
  height: 46px;
  background-color: #19fb9b;
  border: 1px solid black;
  border-radius: 6px;
  cursor: pointer;
  font-size: 17px;
  transition: .4s;
}

.__UIV_SCOPE__ button:hover {
  box-shadow: 5px 6px 0px rgb(0, 0, 0);
}


